"use strict";
const $ = (id) => document.getElementById(id);
const state = {projectId:null,requestId:null,caseId:null,request:null,case:null,automation:null,orchestration:null,management:null,testCaseModification:null,copilotTask:null,traceability:null,codeGraph:null,humanTaskLease:null,taskManagement:{tasks:[],graphTasks:[],selectedId:null,selectedTask:null,graphRunId:null,graphMeta:null,monitoring:null},taskManagementLease:null,taskManagementActionReasons:{},uiKnowledge:null,profileRegistry:null,unresolvedEvidence:null,readiness:null,pollTimer:null};

function actor(){const value=$("actor").value.trim();if(!value)throw new Error("確認者を入力してください");sessionStorage.setItem("operamind.actor",value);return value}
function key(prefix){return `${prefix}-${Date.now()}-${crypto.randomUUID()}`}
async function api(path, options={}){OperaMindLayout.setBusy(true);try{const response=await fetch(path,{...options,headers:{"Content-Type":"application/json",...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.message||`リクエストに失敗しました (${response.status})`);return body}finally{OperaMindLayout.setBusy(false)}}
function notify(message,error=false){const node=document.createElement("div");node.className=`notice ${error?"error":"success"}`;node.setAttribute("role",error?"alert":"status");const content=document.createElement("span");content.textContent=message;const close=document.createElement("button");close.type="button";close.className="notice-close";close.setAttribute("aria-label","通知を閉じる");close.textContent="×";close.addEventListener("click",()=>node.remove());node.append(content,close);$("notice").append(node);setTimeout(()=>node.remove(),error?8000:4200)}
function confirmAction(message){return globalThis.confirm(message)}
function show(id,visible=true){$(id).classList.toggle("hidden",!visible)}
function text(value){if(value===null||value===undefined)return "—";if(typeof value==="object")return JSON.stringify(value,null,2);return String(value)}
function statusClass(status){return ["passed","confirmed","completed","valid","active","active_editing","accepted","in_progress","ready","covered","not_required","approved","unique_visible","current","clear","closed","succeeded","in_scope","auto_confirmed","reviewed","prepared","ok","online"].includes(status)?"good":["failed","blocked","expired","revision_requested","interrupted","reanalysis_required","needs_reanalysis","uncovered","rejected","not_found","hidden","ambiguous","navigation_failed","needs_evidence","missing","open","unresolved","revoked","wrong","offline"].includes(status)?"bad":"warn"}
function statusLabel(status){return globalThis.OperaMindUiCopy?.statusLabel(status)||status}
function changeSummary(change){const fact=({screen_element:"画面項目",api_endpoint:"API エンドポイント",business_rule:"業務ルール"})[change.fact_type]||change.fact_type;return `${fact}の${statusLabel(change.change_type)}`}
function actionLabel(action){return OperaMindChangeManagement.actionLabel(action)}
function dataActionLabel(action){return OperaMindChangeManagement.dataActionLabel(action)}
function scenarioLabel(item){return OperaMindChangeManagement.scenarioLabel(item)}
function scenarioExpected(item){return OperaMindChangeManagement.scenarioExpected(item)}
function gateLabel(gate){return ({golden_dataset:"正式テストデータセット",embedding_provider_live:"埋め込みプロバイダー実動作",human_approval_e2e:"人による承認の一連検証",github_copilot_live:"GitHub Copilot 実動作",target_deployment_e2e:"対象環境 UI 一連検証",full_local_regression:"ローカル全回帰テスト"})[gate]||gate}
function channelLabel(channel){return OperaMindTestDataManagement.channelLabel(channel)}
function operatorLabel(operator){return OperaMindTestDataManagement.operatorLabel(operator)}
function expectedLabel(value){const variable=typeof value==="string"&&value.match(/^\{\{([A-Za-z_][A-Za-z0-9_]*)\}\}$/);if(variable)return`変数「${variable[1]}」`;return ({"totalElements equals four":"totalElements が 4 になる","All four seeded expenses are displayed":"登録済みの 4 件をすべて表示する","All five expenses are displayed":"5 件の経費をすべて表示する","Only the returned expense is displayed":"差戻し経費だけを表示する","passed":"合格"})[value]||text(value)}
function subjectLabel(subject){return ({employeeNo:"社員番号",expenseNo:"経費番号","employee.employeeNo":"社員番号","matching_row.employee_name":"一覧行の社員名","matching_row.expenseNo":"一覧行の経費番号",expense_count:"経費件数",employee_count:"社員件数",status_code:"HTTP ステータス"})[subject]||subject}
function assertionText(assertion){return `${channelLabel(assertion.observe_via)} で「${subjectLabel(assertion.subject)}」${operatorLabel(assertion.operator)} ${expectedLabel(assertion.expected)}`}
function flowTitleLabel(flow){const prefix="Generate reviewed data set ";return flow.title?.startsWith(prefix)?`レビュー済みデータセット ${flow.title.slice(prefix.length)} を生成`:flow.title||flow.flow_id}
function businessActionLabel(action){return ({"load default seed":"既定データをロードする","create returned expense":"差戻し経費を登録する"})[action]||action}
function cleanupPolicyLabel(policy){return ({isolated_environment:"隔離環境",delete_after_run:"実行終了後に作成データを削除",retain:"データを保持",delete_created_records:"作成データを削除",restore_snapshot:"スナップショットを復元"})[policy]||policy||"未指定"}
function blockingReasonLabel(reason){return OperaMindVerificationResults.blockingReasonLabel(reason)}
function screenLabel(value){return OperaMindTestDataManagement.screenLabel(value)}
function uiActionLabel(value){return OperaMindTestDataManagement.uiActionLabel(value)}
function stepTargetLabel(step){return OperaMindTestDataManagement.stepTargetLabel(step)}
function inputVariableNames(value){return OperaMindTestDataManagement.inputVariableNames(value)}
function appendVariableList(row,label,variables){if(!variables.length)return;const variableBox=document.createElement("div");variableBox.className="variable-list";const heading=document.createElement("span");heading.textContent=label;variableBox.append(heading);for(const variable of variables){const chip=document.createElement("code");chip.textContent=variable;variableBox.append(chip)}row.append(variableBox)}
function testSummaryLabel(summary){return ({"Required UI Scenario has no verification result.":"必要な UI シナリオの検証結果がありません。","Committed Edit Result test evidence is missing.":"コミット済みの変更実行結果にテスト証跡がありません。","Committed Edit Result has no command test evidence.":"コミット済みの変更実行結果にコマンドテスト証跡がありません。","Approved deterministic command suite passed.":"承認済みの決定的コマンドテストが合格しました。","Approved deterministic command suite failed.":"承認済みの決定的コマンドテストが失敗しました。","Test data execution is blocked.":"テストデータ実行がブロックされています。","Test data execution is failed.":"テストデータ実行が失敗しました。"})[summary]||summary||"概要はありません。"}
function gateReason(gate){if(gate.status!=="pending")return `${gate.evidence_count} 件の検証済み証跡`;return ({github_copilot_live:"対象範囲の変更とコマンド検証に結び付く、レビュー済みの VS Code GitHub Copilot 実行記録がありません。",target_deployment_e2e:"対象リビジョンに結び付き、すべての証跡が揃った UI 配置テストの合格記録がありません。",full_local_regression:"現在のソースに対する全回帰テストの再実行が必要です。"})[gate.gate_id]||"必要な検証証跡がまだありません。"}
function badge(label,status){const node=document.createElement("span");node.className=`badge ${statusClass(status)}`;node.textContent=statusLabel(label);return node}

const WORKFLOW_STEPS=Object.freeze([
  {label:"変更要件",target:"requestPanel",view:"change"},
  {label:"文書差分",target:"diffPanel",view:"change"},
  {label:"影響範囲",target:"impactPanel",view:"change"},
  {label:"実装・テスト編成",target:"orchestrationPanel",view:"change"},
  {label:"実行許可",target:"grantPanel",view:"change"},
  {label:"VS Code 変更",target:"copilotBridgePanel",view:"change"},
  {label:"テスト実行",target:"testDataManagementPanel",view:"tests"},
  {label:"完了判定",target:"closureManagementPanel",view:"tests"},
]);

function workbenchModel(){
  const request=state.request,progress=state.case?.progress||{},management=state.management||{},reviewed=request?.document_review?.status==="confirmed",confirmed=Boolean(progress.confirmation?.id),orchestrated=Boolean(state.orchestration),granted=Boolean(progress.approval_grant?.id),copilotState=state.copilotTask?.state,testExecution=management.test_data_execution,closure=management.change_closure;
  const completed=[
    Boolean(request),
    reviewed,
    confirmed,
    orchestrated,
    granted,
    ["accepted","in_progress","completed","succeeded"].includes(copilotState),
    ["passed","completed","succeeded"].includes(testExecution?.status),
    ["passed","completed","closed"].includes(closure?.status),
  ];
  const pending=[];
  if(request&&!reviewed)pending.push("文書差分");
  if(reviewed&&state.case&&!confirmed)pending.push("影響範囲");
  if(progress.edit_packet?.id&&!granted)pending.push("実行範囲");
  if(["ready_for_confirmation","needs_confirmation"].includes(state.testCaseModification?.latest?.state))pending.push("テストケース差分");
  if(management.controls?.requires_scope_confirmation)pending.push("改訂後の実行範囲");
  const failures=management.failure_management?.failures||[],unresolved=closure?.unresolved_items||[];
  const blocker=state.automation?.blocking_reason||failures[0]?.summary_ja||(unresolved[0]?blockingReasonLabel(unresolved[0]):null);
  let next={label:"変更要件を入力",detail:"業務目標と期待結果を入力します。",target:"requestPanel",view:"change",hint:"変更要件を登録すると、次の判断地点を自動で案内します。"};
  if(!request){/* 変更未選択時は既定の入力案内を表示する */}
  else if(!reviewed)next={label:"文書差分を確認",detail:"変更前後の設計差分と確認メモをレビューします。",target:"diffPanel",view:"change",hint:"文書差分の確認後に、コードとテストへの影響分析へ進みます。"};
  else if(!state.case)next={label:"分析ケースを関連付け",detail:"VS Code で生成した分析ケースを変更要件に関連付けます。",target:"automationPanel",view:"change",hint:"分析ケースが関連付けられるまで、影響範囲の正式確認には進めません。"};
  else if(reviewed&&state.case&&!confirmed)next={label:"影響範囲を確定",detail:"対象コードと推奨操作を項目ごとに確認します。",target:"impactPanel",view:"change",hint:"影響範囲を確定すると、実装・テスト計画を生成できます。"};
  else if(confirmed&&!orchestrated)next={label:"実装・テストを編成",detail:"コード範囲、テスト、データ、検証基準を生成します。",target:"orchestrationPanel",view:"change",hint:"生成後も自然言語でテストケースを修正できます。"};
  else if(orchestrated&&!granted)next={label:"実行範囲を承認",detail:"コマンド、テスト集合、有効期限を限定して許可します。",target:"grantPanel",view:"change",hint:"実行許可は表示された範囲だけに限定されます。"};
  else if(granted&&progress.edit_packet?.id&&!state.copilotTask)next={label:"VS Code に通知",detail:"承認済み変更を隔離ワークスペースへ通知します。",target:"copilotBridgePanel",view:"change",hint:"VS Code 上の GitHub Copilot が変更を受信し、結果を OperaMind に返します。"};
  else if(!["passed","completed","succeeded"].includes(testExecution?.status))next={label:"テスト結果を確認",detail:"データ生成、UI、クリーンアップと失敗理由を確認します。",target:"testDataManagementPanel",view:"tests",hint:"テスト実行は承認済み範囲内でのみ開始・再試行できます。"};
  else if(!["passed","completed","closed"].includes(closure?.status))next={label:"完了条件を確認",detail:"カバレッジ、証跡、テスト結果とブロック理由を確認します。",target:"closureManagementPanel",view:"tests",hint:"ブロック理由が残る場合は、対応するテストまたは証跡を更新してください。"};
  else next={label:"証跡を確認",detail:"変更追跡とリリース準備状況を最終確認します。",target:"traceabilityPanel",view:"evidence",hint:"すべての正式証跡と準備状況を確認できます。"};
  if(blocker){
    if(failures.length)next={label:"ブロック理由を確認",detail:failures[0].summary_ja,target:"failureManagementPanel",view:"tests",hint:"失敗分類と安全な再開操作を確認してから進めてください。"};
    else if(unresolved.length)next={label:"完了ブロックを確認",detail:blockingReasonLabel(unresolved[0]),target:"closureManagementPanel",view:"tests",hint:"未解決項目に対応するテストまたは証跡を更新してください。"};
    else next={label:"停止地点を確認",detail:blocker,target:"automationPanel",view:"change",hint:"一括編成が停止した理由と必要な人の判断を確認してください。"};
  }
  return {request,completed,pending,blocker,next,percent:Math.round(completed.filter(Boolean).length/completed.length*100)};
}

function navigateToWorkbenchTarget(target,view){
  OperaMindLayout.activateView(view,{focus:false});
  const panel=$(target);
  if(panel&&!panel.classList.contains("hidden")){
    panel.scrollIntoView({behavior:"smooth",block:"start"});
    panel.querySelector("h2,h3,input,textarea,select,button")?.focus({preventScroll:true});
  }else{
    $("workbenchOverviewPanel").scrollIntoView({behavior:"smooth",block:"start"});
  }
}

function renderWorkbench(){
  const model=workbenchModel(),requestLabel=model.request?.requirement_text||state.requestId||"未選択";
  $("workbenchCurrentChange").textContent=requestLabel;
  $("workbenchCurrentDetail").textContent=state.requestId?`変更番号 ${state.requestId}${state.caseId?` · 分析ケース ${state.caseId}`:" · 分析ケース未関連"}`:"左の一覧から変更要件を選択してください。";
  $("workbenchPendingCount").textContent=`${model.pending.length} 件`;
  $("workbenchPendingDetail").textContent=model.pending.length?`${model.pending.join("、")}の確認が必要です。`:"確認待ちはありません。";
  $("workbenchBlockerState").textContent=model.blocker?"あり":"なし";
  $("workbenchBlockerDetail").textContent=model.blocker||"進行を妨げる理由はありません。";
  $("workbenchProgressValue").textContent=`${model.percent}%`;
  $("workbenchProgressBar").style.width=`${model.percent}%`;
  $("workbenchProgressDetail").textContent=`${model.completed.filter(Boolean).length} / ${model.completed.length} 工程が完了`;
  $("workbenchNextAction").textContent=model.next.label;
  $("workbenchNextDetail").textContent=model.next.detail;
  $("workbenchActionHint").textContent=model.next.hint;
  $("workbenchPrimaryAction").textContent=model.next.label;
  $("workbenchPrimaryAction").dataset.target=model.next.target;
  $("workbenchPrimaryAction").dataset.targetView=model.next.view;
  const status=model.blocker?"blocked":model.pending.length?"pending":model.percent===100?"completed":state.requestId?"in_progress":"neutral",stateBadge=$("workbenchStateBadge");
  stateBadge.textContent=model.blocker?"ブロックあり":model.pending.length?`${model.pending.length} 件の確認待ち`:model.percent===100?"全工程完了":state.requestId?"進行中":"変更未選択";
  stateBadge.className=`badge ${status==="neutral"?"neutral":statusClass(status)}`;
  const navigator=$("workflowNavigator");navigator.replaceChildren();
  const currentIndex=({requestPanel:0,diffPanel:1,automationPanel:1,impactPanel:2,orchestrationPanel:3,grantPanel:4,copilotBridgePanel:5,testDataManagementPanel:6,failureManagementPanel:6,closureManagementPanel:7,traceabilityPanel:7})[model.next.target]??model.completed.findIndex(value=>!value);
  WORKFLOW_STEPS.forEach((step,index)=>{const button=document.createElement("button");button.type="button";const stepStatus=index===currentIndex?"current":model.completed[index]?"completed":"pending";button.className=`workflow-step ${stepStatus}`;button.textContent=`${index+1}. ${step.label}`;button.setAttribute("aria-label",`${step.label}へ移動。${stepStatus==="completed"?"完了":stepStatus==="current"?"現在の工程":"未完了"}`);if(stepStatus==="current")button.setAttribute("aria-current","step");button.addEventListener("click",()=>navigateToWorkbenchTarget(step.target,step.view));navigator.append(button)});
}

function renderTraceability(traceability){
  const summary=$("traceabilitySummary"),gapsBox=$("traceabilityGaps"),badgeNode=$("traceabilityBadge");
  if(!traceability){show("traceabilityPanel",false);return}
  show("traceabilityPanel",true);
  const model=OperaMindTraceabilityView.buildGraph(traceability),hasGaps=model.gaps.length>0;
  badgeNode.textContent=hasGaps?`不足 ${model.gaps.length} 件`:"関連付け完了";
  badgeNode.className=`badge ${hasGaps?"bad":"good"}`;
  summary.className=`management-summary${hasGaps?" attention":""}`;
  summary.textContent=`ノード ${model.nodes.length} 件 · 関係 ${model.edges.length} 件 · 必須工程の不足 ${model.summary.critical_gap_count} 件 · 重要経路 ${model.criticalPath.length} ノード · ブロック経路 ${model.blockingChain.length} ノード`;
  gapsBox.replaceChildren();
  for(const gap of model.gaps){const card=document.createElement("article");card.className=`traceability-gap${gap.severity==="warning"?" warning":""}`;const title=document.createElement("strong");title.textContent=`${gap.label}：${gap.message}`;const ref=document.createElement("small");ref.textContent=gap.node_id?`対象：${gap.node_id}`:"対象：変更要件";card.append(title,ref);gapsBox.append(card)}
  renderRelationGraph({
    model,api:OperaMindTraceabilityView,svgId:"traceabilityGraph",viewportId:"traceabilityGraphViewport",
    controlsId:"traceabilityGraphControls",detailId:"traceabilityNodeDetail",
    detail(node){return [`工程：${node.stageLabel}`,`状態：${statusLabel(node.status)}`,`証跡参照：${(node.refs||[]).join("、")||"なし"}`]},
  });
}

function renderCodeGraph(){
  const panel=$("codeGraphPanel"),summary=$("codeGraphSummary"),badgeNode=$("codeGraphBadge");
  if(!state.codeGraph){show("codeGraphPanel",Boolean(state.case?.impact_report?.code_graph_snapshot_id));return}
  show("codeGraphPanel",true);
  const model=OperaMindCodeGraph.buildGraph(state.codeGraph),meta=state.codeGraph.summary||{};
  badgeNode.textContent=statusLabel(state.codeGraph.scan_status);
  badgeNode.className=`badge ${statusClass(state.codeGraph.scan_status)}`;
  summary.className=`management-summary${meta.unresolved_edge_count?" attention":""}`;
  summary.textContent=`ノード ${model.nodes.length} 件 · 関係 ${model.edges.length} 件 · 未解決 ${meta.unresolved_edge_count||0} 件 · 重要経路 ${model.criticalPath.length} ノード · ブロック経路 ${model.blockingChain.length} ノード${meta.truncated?` · 全体 ${meta.total_node_count} ノード / ${meta.total_edge_count} 関係から上限内を表示`:""}`;
  renderRelationGraph({
    model,api:OperaMindCodeGraph,svgId:"codeGraph",viewportId:"codeGraphViewport",
    controlsId:"codeGraphControls",detailId:"codeGraphNodeDetail",
    detail(node){return [`種別：${node.kind==="file"?"ファイル":node.kind==="symbol"?"シンボル":"未解決の参照先"}`,`パス：${node.path||"なし"}`,node.symbol_type?`シンボル種別：${node.symbol_type}`:"",node.start_line?`行：${node.start_line}～${node.end_line}`:""].filter(Boolean)},
  });
}

function renderRelationGraph({model,api,svgId,viewportId,controlsId,detailId,detail}){
  const svg=$(svgId),viewport=$(viewportId),detailBox=$(detailId);
  svg.replaceChildren();
  if(!model.nodes.length){detailBox.className="graph-node-detail empty";detailBox.textContent="表示できるノードがありません。";return}
  const markerId=`${svgId}Arrow`,criticalMarkerId=`${svgId}CriticalArrow`,blockedMarkerId=`${svgId}BlockedArrow`;
  const defs=taskGraphSvgElement("defs");addRelationGraphMarker(defs,markerId,"normal");addRelationGraphMarker(defs,criticalMarkerId,"critical");addRelationGraphMarker(defs,blockedMarkerId,"blocking");svg.append(defs);
  const stage=taskGraphSvgElement("g",{class:"graph-stage"}),nodesById=new Map(model.nodes.map(node=>[node.id,node]));
  const edgeLayer=taskGraphSvgElement("g",{class:"relation-graph-edges"});
  for(const edge of model.edges){const classes=["relation-graph-edge"];if(edge.critical)classes.push("critical");if(edge.blocking)classes.push("blocking");const path=taskGraphSvgElement("path",{d:api.edgePath(edge,nodesById),class:classes.join(" "),"marker-end":`url(#${edge.blocking?blockedMarkerId:edge.critical?criticalMarkerId:markerId})`});const title=taskGraphSvgElement("title");title.textContent=edge.relation||edge.type||"関係";path.append(title);edgeLayer.append(path)}
  const nodeLayer=taskGraphSvgElement("g",{class:"relation-graph-nodes"});
  for(const node of model.nodes){const classes=["relation-graph-node",`kind-${node.kind||"stage"}`];if(node.critical)classes.push("critical");if(node.blocked)classes.push("blocked");if(node.blockedBy?.length)classes.push("propagated");if(node.cycle)classes.push("cycle");const group=taskGraphSvgElement("g",{class:classes.join(" "),transform:`translate(${node.x} ${node.y})`,tabindex:"0",role:"button","data-graph-node":node.id,"aria-label":`${node.title}。${node.stageLabel||node.kind||""}`});const title=taskGraphSvgElement("title");title.textContent=`${node.title}\n${detail(node).join("\n")}`;const rect=taskGraphSvgElement("rect",{width:node.width,height:node.height,rx:"10"});const heading=taskGraphSvgElement("text",{x:"12",y:"24",class:"relation-graph-node-title"});heading.textContent=shortTaskGraphText(node.title,26);const kind=taskGraphSvgElement("text",{x:"12",y:"47",class:"relation-graph-node-kind"});kind.textContent=node.stageLabel||(node.kind==="file"?"ファイル":node.kind==="symbol"?"シンボル":"未解決の参照先");const stateText=taskGraphSvgElement("text",{x:"12",y:"65",class:"relation-graph-node-state"});stateText.textContent=node.blocked?"ブロック元":node.blockedBy?.length?`上流ブロック ${node.blockedBy.length}`:statusLabel(node.status||"");group.append(title,rect,heading,kind,stateText);const select=()=>{for(const value of svg.querySelectorAll(".relation-graph-node.selected"))value.classList.remove("selected");group.classList.add("selected");detailBox.replaceChildren();const name=document.createElement("strong");name.textContent=node.title;detailBox.append(name);for(const line of detail(node)){const item=document.createElement("span");item.textContent=line;detailBox.append(item)}detailBox.className="graph-node-detail"};group.addEventListener("click",select);group.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();select()}});nodeLayer.append(group)}
  stage.append(edgeLayer,nodeLayer);svg.append(stage);
  OperaMindGraphCanvas.attach({viewport,svg,stage,controls:$(controlsId),width:model.width,height:model.height});
}

function addRelationGraphMarker(defs,id,className){const marker=taskGraphSvgElement("marker",{id,viewBox:"0 0 10 10",refX:"9",refY:"5",markerWidth:"7",markerHeight:"7",orient:"auto-start-reverse"});marker.append(taskGraphSvgElement("path",{d:"M 0 0 L 10 5 L 0 10 z",class:`relation-graph-marker ${className}`}));defs.append(marker)}

function renderChangedLineCoverage(management){const summary=$("changedLineCoverageSummary"),files=$("changedLineCoverageFiles"),model=OperaMindVerificationResults.coverageView(management?.business_coverage,management?.changed_line_coverage).changedLines;summary.replaceChildren();files.replaceChildren();if(!model){summary.className="coverage-summary empty";summary.textContent="変更行カバレッジはまだ生成されていません。";return}summary.className="coverage-summary";const label=document.createElement("div");label.className="coverage-label";const percent=document.createElement("strong");percent.textContent=model.status==="not_required"?"対象外":`${model.percent}%`;const detail=document.createElement("span");detail.textContent=model.status==="not_required"?"実行可能な変更行はありません":`${model.covered} / ${model.total} 変更行 · 基準 ${model.threshold}% · 証跡 ${model.evidenceRefs.length} 件`;label.append(percent,detail);const meter=document.createElement("div");meter.className="coverage-meter";const fill=document.createElement("span");fill.style.width=`${model.percent??100}%`;meter.append(fill);summary.append(label,meter,badge(model.status,model.status));if(model.blockingReasons.length){const blockers=document.createElement("ul");blockers.className="blocking-list";for(const reason of model.blockingReasons){const item=document.createElement("li");item.textContent=reason.label;blockers.append(item)}summary.append(blockers)}for(const file of model.files){const row=document.createElement("div");row.className="coverage-item";const info=document.createElement("div");const name=document.createElement("strong");name.textContent=file.path;const lines=document.createElement("small");const uncovered=(file.uncovered_changed_lines||[]).join("、")||"なし";lines.textContent=`カバー済み ${file.covered_changed_line_count} / ${file.changed_line_count} · 未カバー行 ${uncovered}`;info.append(name,lines);row.append(info);files.append(row)}}

