function taskFilterStates(){const value=$("taskStateFilter").value;if(value==="ready")return["ready"];if(value==="active")return["claimed","running","submitted"];if(value==="blocked")return["blocked","failed"];if(value==="completed")return["completed"];return[]}
async function loadTaskManagement(){const parameters=new URLSearchParams({limit:"200"}),graphParameters=new URLSearchParams({limit:"500"}),monitoringParameters=new URLSearchParams({window_hours:$("taskMonitoringWindow").value||"24"});if(state.projectId){parameters.set("project_id",state.projectId);graphParameters.set("project_id",state.projectId);monitoringParameters.set("project_id",state.projectId)}for(const value of taskFilterStates())parameters.append("state",value);const capability=$("taskCapabilityFilter").value.trim(),reason=$("taskBlockingReasonFilter").value.trim();if(capability)parameters.set("capability",capability);if(reason)parameters.set("blocking_reason",reason);const [result,graph,monitoring]=await Promise.all([api(`/api/v1/orchestration-tasks/management?${parameters}`),api(`/api/v1/orchestration-tasks/graph?${graphParameters}`),api(`/api/v1/orchestration-tasks/monitoring?${monitoringParameters}`)]);state.taskManagement.tasks=result.tasks||[];state.taskManagement.graphTasks=graph.tasks||[];state.taskManagement.graphMeta=graph;state.taskManagement.monitoring=monitoring;if(!state.taskManagement.tasks.some(task=>task.orchestration_task_id===state.taskManagement.selectedId))state.taskManagement.selectedId=state.taskManagement.tasks[0]?.orchestration_task_id||null;state.taskManagement.selectedTask=state.taskManagement.tasks.find(task=>task.orchestration_task_id===state.taskManagement.selectedId)||null;renderTaskManagement()}
function renderTaskManagement(){const tasks=state.taskManagement.tasks,summary=$("taskManagementSummary"),queue=$("taskManagementQueue");summary.className=`management-summary${tasks.some(task=>["blocked","failed"].includes(task.state))?" attention":""}`;summary.textContent=`表示 ${tasks.length} 件 · 実行待ち ${tasks.filter(task=>(task.effective_state||task.state)==="ready").length} · 実行中 ${tasks.filter(task=>["claimed","running"].includes(task.state)).length} · 照合待ち ${tasks.filter(task=>task.state==="submitted").length} · ブロック ${tasks.filter(task=>["blocked","failed"].includes(task.state)).length}`;renderTaskMonitoring();renderTaskDependencyGraph();queue.replaceChildren();if(!tasks.length){queue.className="task-management-queue empty";queue.textContent="条件に一致する作業はありません。";renderTaskManagementDetail(state.taskManagement.selectedTask);return}queue.className="task-management-queue";for(const task of tasks){const card=document.createElement("button");card.type="button";card.className=`task-card ${task.state}${task.orchestration_task_id===state.taskManagement.selectedId?" selected":""}`;const heading=document.createElement("div");heading.className="task-card-heading";const title=document.createElement("strong");title.textContent=`#${task.sequence} ${task.title}`;heading.append(title,badge(task.effective_state||task.state,task.effective_state||task.state));const meta=document.createElement("span");meta.className="task-card-meta";meta.textContent=`実行 ${task.automation_run_id} · 変更 ${task.change_request_id}`;const capability=document.createElement("span");capability.className="task-card-capability";capability.textContent=`実行能力：${(task.required_capabilities||[]).join(" / ")}`;card.append(heading,meta,capability);if(task.blocking_reason){const reason=document.createElement("span");reason.className="task-blocking-reason";reason.textContent=task.blocking_reason;card.append(reason)}card.addEventListener("click",()=>selectTaskManagementTask(task.orchestration_task_id));queue.append(card)}renderTaskManagementDetail(state.taskManagement.selectedTask||tasks.find(task=>task.orchestration_task_id===state.taskManagement.selectedId)||null)}
function renderTaskMonitoring(){
  const monitoring=state.taskManagement.monitoring,metrics=$("taskMonitoringMetrics"),workers=$("taskWorkerStatus"),blockers=$("taskBlockerRanking");
  metrics.replaceChildren();workers.replaceChildren();blockers.replaceChildren();
  if(!monitoring){metrics.className="task-monitoring-metrics empty";metrics.textContent="実行指標を読み込んでいます。";return}
  metrics.className="task-monitoring-metrics";
  const values=[["実行待ちの滞留",`${monitoring.ready_count||0} 件`],["最長待機時間",taskDuration(monitoring.oldest_ready_wait_seconds)],["平均待機時間",taskDuration(monitoring.average_queue_wait_seconds)],["待機時間 P95",taskDuration(monitoring.p95_queue_wait_seconds)],["平均実行時間",taskDuration(monitoring.average_execution_seconds)],["成功率",monitoring.success_rate==null?"対象なし":`${Math.round(monitoring.success_rate*100)}%`],["再試行",`${monitoring.retry_count} 回`],["担当期限切れ",`${monitoring.lease_expiry_count} 件`]];
  for(const [label,value] of values){const card=document.createElement("div");card.className="task-monitoring-metric";const name=document.createElement("span");name.textContent=label;const number=document.createElement("strong");number.textContent=value;card.append(name,number);metrics.append(card)}
  for(const alert of monitoring.alerts||[]){const card=document.createElement("div");card.className=`task-monitoring-metric alert ${alert.severity||"warning"}`;const name=document.createElement("span");name.textContent=({queue_backlog:"待機作業の滞留",task_timeout:"作業タイムアウト",queue_wait:"待機時間超過"})[alert.alert_type]||"運用アラート";const number=document.createElement("strong");number.textContent=`${alert.value}（閾値 ${alert.threshold}）`;card.append(name,number);metrics.append(card)}
  renderWorkerOperations(monitoring.workers||[],workers);
  const blockerValues=monitoring.blocker_reasons||[];blockers.className=blockerValues.length?"task-blocker-ranking":"task-blocker-ranking empty";if(!blockerValues.length)blockers.textContent="集計期間内のブロックはありません。";for(const blocker of blockerValues){const row=document.createElement("div");row.className="task-blocker-row";const text=document.createElement("div");const reason=document.createElement("strong");reason.textContent=blocker.reason;const latest=document.createElement("small");latest.textContent=`最終発生 ${taskTime(blocker.latest_at)}`;text.append(reason,latest);const count=document.createElement("span");count.textContent=`${blocker.occurrence_count} 件`;row.append(text,count);blockers.append(row)}
}
function renderWorkerOperations(workerValues,workers){
  workers.className=workerValues.length?"task-worker-status":"task-worker-status empty";
  if(!workerValues.length){workers.textContent="登録済みの実行担当はありません。";return}
  for(const worker of workerValues){
    const card=document.createElement("article");card.className=`task-worker-card status-${worker.status}`;card.dataset.executorKind=worker.executor_kind;card.dataset.executorId=worker.executor_id;
    const heading=document.createElement("div");heading.className="task-worker-heading";const text=document.createElement("div");const name=document.createElement("strong");name.textContent=`${worker.executor_kind} · ${worker.executor_id}`;const detail=document.createElement("small");detail.textContent=`稼働 ${worker.active_task_count}/${worker.max_concurrent_tasks} · 最終通信 ${taskTime(worker.last_seen_at)}`;text.append(name,detail);heading.append(text,badge(workerStatusLabel(worker),worker.status==="online"&&worker.present?"completed":worker.status==="draining"?"pending":"failed"));
    const form=document.createElement("div");form.className="task-worker-config";const capabilityLabel=document.createElement("label");capabilityLabel.textContent="実行能力";const capability=document.createElement("input");capability.className="task-worker-capabilities";capability.maxLength=4000;capability.value=(worker.capabilities||[]).join(", ");capabilityLabel.append(capability);const concurrencyLabel=document.createElement("label");concurrencyLabel.textContent="並行上限";const concurrency=document.createElement("input");concurrency.className="task-worker-concurrency";concurrency.type="number";concurrency.min="1";concurrency.max="100";concurrency.value=String(worker.max_concurrent_tasks);concurrencyLabel.append(concurrency);const save=document.createElement("button");save.type="button";save.className="secondary compact";save.textContent="設定を保存";save.addEventListener("click",()=>updateManagedWorker(worker,card).catch(error=>notify(error.message,true)));form.append(capabilityLabel,concurrencyLabel,save);
    const actions=document.createElement("div");actions.className="task-worker-actions";for(const [operation,label] of [["enable","有効化"],["drain","新規受付を終了"],["disable","停止"]]){const button=document.createElement("button");button.type="button";button.className=operation==="enable"?"primary compact":operation==="disable"?"danger compact":"secondary compact";button.textContent=label;button.disabled=(operation==="enable"&&worker.status==="online")||(operation==="drain"&&worker.status==="draining")||(operation==="disable"&&worker.status==="offline");button.addEventListener("click",()=>operateManagedWorker(worker,operation).catch(error=>notify(error.message,true)));actions.append(button)}
    const events=document.createElement("ol");events.className="task-worker-events";for(const event of (worker.events||[]).slice(0,3)){const item=document.createElement("li");item.textContent=`#${event.sequence} ${workerEventLabel(event.event_type)} · ${event.actor} · ${taskTime(event.created_at)}`;events.append(item)}
    card.append(heading,form,actions,events);workers.append(card);
  }
}
function workerStatusLabel(worker){if(worker.status==="draining")return worker.present?"新規受付を終了中":"新規受付終了・未接続";if(worker.status==="offline")return worker.present?"停止（接続あり）":"停止";return worker.present?"オンライン":"有効・接続待ち"}
function workerEventLabel(value){return({registered:"登録",enabled:"有効化",disabled:"停止",drain_requested:"新規受付終了",configuration_updated:"設定変更"})[value]||value}
async function operateManagedWorker(worker,operation){if(operation==="disable"&&!confirmAction(`実行担当「${worker.executor_id}」を停止します。実行中の作業と後続処理への影響を確認しましたか？`))return;await api(`/api/v1/orchestration-tasks/workers/${encodeURIComponent(worker.executor_kind)}/${encodeURIComponent(worker.executor_id)}/${operation}`,{method:"POST",headers:{"X-OperaMind-Actor":actor(),"Idempotency-Key":key(`worker-${operation}`)}});await loadTaskManagement();notify(operation==="enable"?"実行担当を有効化しました":operation==="drain"?"実行担当の新規受付を終了しました":"実行担当を停止しました")}
async function updateManagedWorker(worker,card){const capabilities=card.querySelector(".task-worker-capabilities").value.split(/[,\n]/).map(value=>value.trim()).filter(Boolean),maximum=Number(card.querySelector(".task-worker-concurrency").value);if(!capabilities.length)throw new Error("実行能力を一つ以上入力してください");if(!Number.isInteger(maximum)||maximum<1||maximum>100)throw new Error("並行上限は 1～100 で入力してください");await api(`/api/v1/orchestration-tasks/workers/${encodeURIComponent(worker.executor_kind)}/${encodeURIComponent(worker.executor_id)}`,{method:"PATCH",headers:{"X-OperaMind-Actor":actor(),"Idempotency-Key":key("worker-config")},body:JSON.stringify({capabilities,max_concurrent_tasks:maximum})});await loadTaskManagement();notify("実行担当の実行能力と並行上限を更新しました")}
function taskDuration(seconds){if(seconds==null)return"対象なし";if(seconds<60)return`${Math.round(seconds)} 秒`;if(seconds<3600)return`${(seconds/60).toFixed(1)} 分`;return`${(seconds/3600).toFixed(1)} 時間`}
async function selectTaskManagementTask(taskId){state.taskManagement.selectedId=taskId;const candidate=[...state.taskManagement.tasks,...state.taskManagement.graphTasks].find(task=>task.orchestration_task_id===taskId);if(candidate?.automation_run_id)state.taskManagement.graphRunId=candidate.automation_run_id;const result=await api(`/api/v1/orchestration-tasks/${encodeURIComponent(taskId)}`);replaceManagedTask(result.task);renderTaskManagement();OperaMindLayout.openDrawer("作業詳細")}
function replaceManagedTask(task){const index=state.taskManagement.tasks.findIndex(value=>value.orchestration_task_id===task.orchestration_task_id),matches=taskMatchesManagementFilters(task);if(index>=0&&matches)state.taskManagement.tasks[index]=task;else if(index>=0)state.taskManagement.tasks.splice(index,1);else if(matches)state.taskManagement.tasks.unshift(task);const graphIndex=state.taskManagement.graphTasks.findIndex(value=>value.orchestration_task_id===task.orchestration_task_id);if(graphIndex>=0)state.taskManagement.graphTasks[graphIndex]=task;else state.taskManagement.graphTasks.unshift(task);state.taskManagement.selectedId=task.orchestration_task_id;state.taskManagement.selectedTask=task}
function taskMatchesManagementFilters(task){const states=taskFilterStates(),effective=task.effective_state||task.state;if(states.length&&!states.includes(effective))return false;const capability=$("taskCapabilityFilter").value.trim();if(capability&&!(task.required_capabilities||[]).includes(capability))return false;const reason=$("taskBlockingReasonFilter").value.trim().toLocaleLowerCase("ja-JP");return !reason||String(task.blocking_reason||"").toLocaleLowerCase("ja-JP").includes(reason)}
function taskTime(value){return value?new Date(value).toLocaleString("ja-JP"):"—"}
function renderTaskDependencyGraph(){
  const allTasks=state.taskManagement.graphTasks||[],runSelect=$("taskGraphRunFilter"),svg=$("taskDependencyGraph"),summary=$("taskGraphSummary"),critical=$("taskGraphCriticalPath");
  const runCounts=new Map();for(const task of allTasks){if(task.automation_run_id)runCounts.set(task.automation_run_id,(runCounts.get(task.automation_run_id)||0)+1)}
  const runs=[...runCounts.keys()].sort();const selectedTask=allTasks.find(task=>task.orchestration_task_id===state.taskManagement.selectedId);
  if(!state.taskManagement.graphRunId||!runCounts.has(state.taskManagement.graphRunId))state.taskManagement.graphRunId=selectedTask?.automation_run_id||runs[0]||null;
  runSelect.replaceChildren();if(!runs.length){const option=document.createElement("option");option.value="";option.textContent="対象実行なし";runSelect.append(option);runSelect.disabled=true}else{runSelect.disabled=false;for(const runId of runs){const option=document.createElement("option");option.value=runId;option.textContent=`実行 ${runId}（${runCounts.get(runId)} 作業）`;runSelect.append(option)}runSelect.value=state.taskManagement.graphRunId}
  svg.replaceChildren();critical.textContent="";if(!state.taskManagement.graphRunId){$("taskGraphViewport")._operaMindGraphCanvas?.destroy?.();summary.textContent="表示できる作業依存関係はありません。";svg.removeAttribute("viewBox");return}
  const tasks=allTasks.filter(task=>task.automation_run_id===state.taskManagement.graphRunId),graphApi=globalThis.OperaMindTaskGraph;if(!graphApi){summary.textContent="作業関係図モジュールを読み込めませんでした。";return}
  const model=graphApi.buildTaskDependencyGraph(tasks),nodesById=new Map(model.nodes.map(node=>[node.id,node]));svg.removeAttribute("width");svg.removeAttribute("height");svg.style.width="100%";svg.style.height="100%";
  const defs=taskGraphSvgElement("defs");addTaskGraphMarker(defs,"taskGraphArrow","normal");addTaskGraphMarker(defs,"taskGraphCriticalArrow","critical");addTaskGraphMarker(defs,"taskGraphBlockedArrow","blocked");svg.append(defs);
  const stage=taskGraphSvgElement("g",{class:"graph-stage"}),edgeLayer=taskGraphSvgElement("g",{class:"task-graph-edges"});for(const edge of model.edges){const classNames=["task-graph-edge"];if(edge.critical)classNames.push("critical");if(edge.blocking)classNames.push("blocking");if(edge.cycle)classNames.push("cycle");const path=taskGraphSvgElement("path",{d:graphApi.edgePath(edge,nodesById),class:classNames.join(" "),"marker-end":`url(#${edge.blocking?"taskGraphBlockedArrow":edge.critical?"taskGraphCriticalArrow":"taskGraphArrow"})`});edgeLayer.append(path)}
  const nodeLayer=taskGraphSvgElement("g",{class:"task-graph-nodes"});for(const node of model.nodes)nodeLayer.append(renderTaskGraphNode(node));stage.append(edgeLayer,nodeLayer);svg.append(stage);OperaMindGraphCanvas.attach({viewport:$("taskGraphViewport"),svg,stage,controls:$("taskGraphControls"),width:model.width,height:model.height});
  const actualBlocks=model.nodes.filter(node=>["blocked","failed"].includes(node.storedState)).length,meta=state.taskManagement.graphMeta;summary.textContent=`${tasks.length} 作業 · ${model.edges.length} 依存 · 重要経路 ${model.criticalPath.length} 作業 · 実ブロック ${actualBlocks} · ブロック伝播 ${model.blockedPropagationCount}${model.cycleNodeIds.length?` · 循環依存 ${model.cycleNodeIds.length}`:""}${meta?.truncated?` · 全 ${meta.total_count} 件中 ${meta.count} 件を表示`:""}`;
  if(model.criticalPath.length){const labels=model.criticalPath.map(id=>{const node=nodesById.get(id);return node.external?`参照外 ${shortTaskGraphText(node.title,18)}`:`#${node.sequence} ${shortTaskGraphText(node.title,18)}`});critical.textContent=`重要経路（依存段数による最長経路）：${labels.join(" → ")}`}
}
function renderTaskGraphNode(node){const classes=["task-graph-node",`state-${String(node.state).replace(/[^a-z_]/g,"")}`];if(node.critical)classes.push("critical");if(node.blockedBy.length)classes.push("propagated");if(node.cycle)classes.push("cycle");if(node.external)classes.push("external");if(node.id===state.taskManagement.selectedId)classes.push("selected");const group=taskGraphSvgElement("g",{class:classes.join(" "),transform:`translate(${node.x} ${node.y})`,tabindex:node.external?"-1":"0",role:node.external?"img":"button","data-task-id":node.id,"data-graph-node":node.id,"aria-label":`${node.title}、状態 ${statusLabel(node.state)}、前置作業 ${node.predecessorCount} 件${node.blockedBy.length?`、上流ブロック ${node.blockedBy.length} 件`:""}`});const title=taskGraphSvgElement("title");title.textContent=`${node.id}\n状態：${statusLabel(node.state)}\n前置作業：${node.predecessorCount}${node.blockingReason?`\nブロック理由：${node.blockingReason}`:""}${node.blockedBy.length?`\n上流ブロック元：${node.blockedBy.join(", ")}`:""}`;const rect=taskGraphSvgElement("rect",{width:node.width,height:node.height,rx:"10"});const heading=taskGraphSvgElement("text",{x:"12",y:"22",class:"task-graph-node-title"});heading.textContent=node.external?`参照外 · ${shortTaskGraphText(node.title,20)}`:`#${node.sequence} ${shortTaskGraphText(node.title,22)}`;const status=taskGraphSvgElement("text",{x:"12",y:"45",class:"task-graph-node-state"});status.textContent=statusLabel(node.state);const detail=taskGraphSvgElement("text",{x:"12",y:"65",class:"task-graph-node-meta"});detail.textContent=node.blockedBy.length?`上流ブロック ${node.blockedBy.length} · 前置 ${node.predecessorCount}`:node.cycle?`循環依存 · 前置 ${node.predecessorCount}`:`前置作業 ${node.predecessorCount}`;group.append(title,rect,heading,status,detail);if(!node.external){const select=()=>selectTaskManagementTask(node.id).catch(error=>notify(error.message,true));group.addEventListener("click",select);group.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();select()}})}return group}
