function renderTimeline(steps){const box=$("timeline");box.replaceChildren();for(const step of steps){const row=document.createElement("div");row.className=`timeline-item ${step.status}`;const dot=document.createElement("span");dot.className="dot";const label=document.createElement("strong");label.textContent=step.label;row.append(dot,label,badge(step.status,step.status));box.append(row)}}
