function renderAutomation(run){const summary=$("automationSummary"),timeline=$("automationTimeline"),events=$("automationEvents"),stateBadge=$("automationState");summary.replaceChildren();timeline.replaceChildren();events.replaceChildren();if(!run){summary.className="automation-summary empty";summary.textContent="一括編成はまだ開始されていません。";stateBadge.textContent="未開始";stateBadge.className="badge neutral";show("resumeAutomation",false);show("humanTaskControls",false);$("startAutomation").disabled=false;return}stateBadge.textContent=statusLabel(run.status);stateBadge.className=`badge ${statusClass(run.status)}`;summary.className="automation-summary";const title=document.createElement("strong");title.textContent=`現在：${run.current_stage_label}`;const next=document.createElement("span");next.textContent=run.blocking_reason?`ブロック理由：${run.blocking_reason}`:`次の操作：${automationActionLabel(run.next_action)}`;summary.append(title,next);const task=run.current_task;if(task){const taskLine=document.createElement("span");taskLine.textContent=`実行作業 #${task.sequence} · ${task.action} · ${statusLabel(task.effective_state||task.state)} · 必要な実行能力 ${(task.required_capabilities||[]).join(" / ")}`;summary.append(taskLine)}renderHumanTaskControls(task);renderAutomationTimeline(run.steps||[]);for(const event of run.events||[]){const item=document.createElement("li");const seq=document.createElement("span");seq.className="event-sequence";seq.textContent=`#${event.sequence}`;const message=document.createElement("span");message.textContent=event.message;item.append(seq,message,badge(event.status,event.status));events.append(item)}show("resumeAutomation",run.status!=="completed");$("startAutomation").disabled=true}
