function renderHumanTaskControls(task){if(task?.lease_expired&&state.humanTaskLease?.taskId===task.orchestration_task_id)state.humanTaskLease=null;const lease=state.humanTaskLease&&state.humanTaskLease.taskId===task?.orchestration_task_id?state.humanTaskLease:null;if(!task){show("humanTaskControls",false);return}show("humanTaskControls");const effective=task.effective_state||task.state;show("claimHumanTask",effective==="ready"&&!lease);show("heartbeatHumanTask",Boolean(lease));show("releaseHumanTask",Boolean(lease));show("humanTaskResultForm",Boolean(lease));show("humanTaskRequeueForm",["blocked","failed"].includes(task.state));const claim=task.claims?.find(value=>value.status==="active");$("humanTaskNote").textContent=lease?`担当中：${lease.executorId}。担当トークンはこの画面のメモリだけに保持します。`:claim?`担当中：${claim.executor_kind} / ${claim.executor_id}。期限切れ後に別の実行者が担当できます。`:`作業 #${task.sequence} を人として担当できます。担当開始だけでは承認になりません。`}
