$("projectSelect").addEventListener("change",async event=>{state.projectId=event.target.value;state.requestId=null;state.caseId=null;state.request=null;state.case=null;state.automation=null;state.orchestration=null;state.management=null;state.testCaseModification=null;state.copilotTask=null;state.taskManagementLease=null;state.taskManagement.graphRunId=null;state.taskManagement.graphTasks=[];$("currentRequest").textContent="未選択";OperaMindLayout.refreshDrawerContext();renderWorkbench();await Promise.all([loadRequests(),loadTaskManagement(),loadUiKnowledgeReviews(),loadProfileRegistry(),loadUnresolvedEvidence()])});$("newRequest").addEventListener("click",()=>{OperaMindLayout.activateView("change",{focus:false});$("requestPanel").scrollIntoView({behavior:"smooth"});$("requestId").focus({preventScroll:true})});
$("workbenchPrimaryAction").addEventListener("click",event=>navigateToWorkbenchTarget(event.currentTarget.dataset.target,event.currentTarget.dataset.targetView));
$("refreshProfileRegistry").addEventListener("click",async()=>{try{await loadProfileRegistry()}catch(error){notify(error.message,true)}});
$("taskGraphRunFilter").addEventListener("change",event=>{state.taskManagement.graphRunId=event.target.value||null;renderTaskDependencyGraph()});
$("taskMonitoringWindow").addEventListener("change",async()=>{try{await loadTaskManagement()}catch(error){notify(error.message,true)}});
$("requestForm").addEventListener("submit",async event=>{event.preventDefault();try{const body={change_request_id:$("requestId").value.trim(),project_id:state.projectId,analysis_case_id:$("caseId").value.trim()||null,input_mode:$("inputMode").value,requirement_text:$("requirement").value.trim()||null,source_document_ref:$("sourceRef").value.trim()||null,target_document_ref:$("targetRef").value.trim()||null,business_rules:[{business_rule_id:`rule-${$("requestId").value.trim()}`,text:$("businessRule").value.trim(),source_refs:[]}],ambiguity_status:"clear",ambiguities:[]};const result=await api("/api/v1/change-requests",{method:"POST",headers:{"X-OperaMind-Actor":actor(),"Idempotency-Key":key("change-request")},body:JSON.stringify(body)});notify(result.created?"変更要件を登録しました":"同じ変更要件が登録済みです");await selectRequest(body.change_request_id)}catch(error){notify(error.message,true)}});
for(const [id,fn] of [["refreshTaskManagement",loadTaskManagement],["applyTaskFilters",loadTaskManagement],["startAutomation",startAutomation],["resumeAutomation",resumeAutomation],["claimHumanTask",claimHumanTask],["heartbeatHumanTask",heartbeatHumanTask],["releaseHumanTask",releaseHumanTask],["submitHumanTaskResult",submitHumanTaskResult],["requeueHumanTask",requeueHumanTask],["confirmDiff",()=>reviewDiff("confirmed")],["reviseDiff",()=>reviewDiff("revision_requested")],["confirmImpact",confirmImpact],["orchestrateChange",orchestrateChange],["modifyTestCase",submitTestCaseModification],["issueGrant",issueGrant],["publishCopilotTask",publishCopilotTask],["cancelCopilotTask",cancelCopilotTask],["retryCopilotTask",retryCopilotTask],["refreshCase",loadCase],["refreshUiKnowledge",loadUiKnowledgeReviews],["refreshUnresolvedEvidence",loadUnresolvedEvidence],["refreshEnvironmentDiagnostics",loadEnvironmentDiagnostics],["startTestData",startTestDataRun],["rerunTestData",rerunTestDataRun],["recoverTestData",()=>recoverTestDataRun()],["failureRecover",()=>recoverTestDataRun("failureRecoveryReason")],["failureRerun",rerunTestDataRun]])$(id).addEventListener("click",async event=>{const button=event.currentTarget;button.setAttribute("aria-busy","true");try{await fn()}catch(error){notify(error.message,true)}finally{button.removeAttribute("aria-busy")}});
$("bindAutomationCase").addEventListener("click",async()=>{try{await bindAutomationCase()}catch(error){notify(error.message,true)}});
renderWorkbench();
Promise.all([loadEnvironmentDiagnostics(),loadReadiness(),loadProjects()]).catch(error=>notify(error.message,true));
